<?php
declare(strict_types=1);
require_once __DIR__.'/../config/bootstrap.php';require_once __DIR__.'/../config/governance.php';$pageTitle=t('legal_public.title');
header('Cache-Control: private, no-store, max-age=0');
$method=$_SERVER['REQUEST_METHOD']??'GET';
if (!in_array($method,['GET','HEAD','POST'],true)) { header('Allow: GET, HEAD, POST'); abort_request(405,t('account.method')); }
$code=is_string($_GET['document']??null)?$_GET['document']:'';$language=is_string($_GET['language']??null)?$_GET['language']:i18n_locale();
if(!preg_match('/\A[a-z]{2}(?:-[A-Z]{2})?\z/',$language))abort_request(400,t('legal_public.invalid_language'));
$enabled=site_setting($pdo,'legal_publication_enabled','0')==='1';$selected=null;$error='';
$versionId=null;
if(array_key_exists('version_id',$_GET)){$versionId=is_string($_GET['version_id'])?filter_var($_GET['version_id'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]):false;if($versionId===false||$code==='')abort_request(400,t('consent.changed'));}
if($code!==''&&(!preg_match('/\A[a-z0-9-]{2,80}\z/',$code)||!$enabled))abort_request(503,t('legal_public.unavailable'));
if($code!==''){$q=$pdo->prepare("SELECT * FROM market_legal_documents WHERE document_code=? AND language=? AND status='approved' AND effective_at<=UTC_TIMESTAMP()".($versionId!==null?' AND id=?':'')." ORDER BY effective_at DESC,id DESC LIMIT 1");$q->execute($versionId!==null?[$code,$language,$versionId]:[$code,$language]);$selected=$q->fetch();if(!$selected)abort_request(404,t('legal_public.missing_language'));try{consent_integrity($selected);}catch(DomainException $e){abort_request(503,$e->getMessage());}}
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){require_csrf();$user=require_login($pdo);try{if(!$selected||post_string('accept_document')!=='1')throw new InvalidArgumentException(t('legal_public.confirm'));if(post_string('document_id')!==(string)$selected['id']||!hash_equals($selected['content_hash'],post_string('document_hash',64)))throw new InvalidArgumentException(t('consent.changed'));legal_accept($pdo,(int)$user['id'],(int)$selected['id'],'updated_terms');$_SESSION['legal_document_accepted']=(int)$selected['id'];redirect('/marketplace/legal.php?document='.rawurlencode($code).'&language='.rawurlencode($language).'&version_id='.(int)$selected['id']);}catch(InvalidArgumentException|DomainException $e){http_response_code(422);$error=$e->getMessage();}}
if($selected&&in_array($method,['GET','HEAD'],true)&&($_GET['download']??'')==='1'){header('Content-Type: text/plain; charset=utf-8');header('Content-Disposition: attachment; filename="gunindex-'.$selected['document_code'].'-'.$selected['version'].'.txt"');echo$selected['body_text'];exit;}
$acceptanceSaved=$method==='GET'&&$selected&&($_SESSION['legal_document_accepted']??null)===(int)$selected['id'];
if($acceptanceSaved)unset($_SESSION['legal_document_accepted']);
$documents=$enabled?$pdo->query("SELECT d.id,d.document_code,d.language,d.title,d.version FROM market_legal_documents d WHERE d.status='approved' AND d.effective_at<=UTC_TIMESTAMP() AND NOT EXISTS(SELECT 1 FROM market_legal_documents n WHERE n.document_code=d.document_code AND n.language=d.language AND n.status='approved' AND n.effective_at<=UTC_TIMESTAMP() AND (n.effective_at>d.effective_at OR (n.effective_at=d.effective_at AND n.id>d.id))) ORDER BY d.title,d.language LIMIT 200")->fetchAll():[];
include __DIR__.'/../includes/header.php';?>
<main class="container"><div class="page-heading"><h1><?=h(t('legal_public.title'))?></h1><p><?=h(t('legal_public.intro'))?></p></div>
<?php if(!$enabled):?><section class="panel"><h2><?=h(t('legal_public.pending'))?></h2><p><?=h(t('legal_public.pending_help'))?></p></section><?php endif;?>
<?php if($error):?><p class="notice error" role="alert"><?=h($error)?></p><?php endif;?><?php if($selected):?><section class="panel"><h2><?=h($selected['title'])?></h2><p><?=h(t('legal_public.version_info',['version'=>$selected['version'],'language'=>$selected['language'],'date'=>$selected['effective_at']]))?></p><p><a class="button secondary" href="?document=<?=h(rawurlencode($code))?>&amp;language=<?=h(rawurlencode($language))?>&amp;version_id=<?=(int)$selected['id']?>&amp;download=1"><?=h(t('legal_public.download'))?></a></p><div style="white-space:pre-wrap;overflow-wrap:anywhere"><?=h($selected['body_text'])?></div><p>SHA-256 <code><?=h($selected['content_hash'])?></code></p>
<?php if($viewer):?><form method="post"><?=csrf_field()?><input type="hidden" name="document_id" value="<?=(int)$selected['id']?>"><input type="hidden" name="document_hash" value="<?=h($selected['content_hash'])?>"><label><input type="checkbox" name="accept_document" value="1" required> <?=h(t('legal_public.confirm_checkbox'))?></label><button class="button" type="submit"><?=h(t('legal_public.accept'))?></button></form><?php endif;?><?php if($acceptanceSaved):?><p class="notice success" role="status"><?=h(t('legal_public.saved'))?></p><?php endif;?></section><?php endif;?>
<section class="panel"><h2><?=h(t('legal_public.versions'))?></h2><?php foreach($documents as $doc):?><p><a href="?document=<?=h(rawurlencode($doc['document_code']))?>&amp;language=<?=h(rawurlencode($doc['language']))?>"><?=h($doc['title'])?> · <?=h($doc['version'])?> / <?=h($doc['language'])?></a></p><?php endforeach;?><?php if(!$documents):?><p><?=h(t('legal_public.empty'))?></p><?php endif;?></section></main><?php include __DIR__.'/../includes/footer.php';?>
